package com.example.crm.auth;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {final JwtService jwt; final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){var u=users.findByUsername(jwt.username(t));if(u.isPresent())SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.get(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.get().getRole()))));}}c.doFilter(r,s);}}
